/*
	Noise Layers #genuary2 #genuary #genuary2502
	Layers upon layers upon layers
	https://openprocessing.org/sketch/2498632
	#generativeart #creativecoding #p5js
*/

const NUM = 3;
const MAR = 0.3; // margin for non filled areas
let SZE = 14 * NUM, CLRS;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("Layers of noise fields");
	frameRate(30);

	CLRS = []
	for (let i = 0; i < NUM; i++) {
		CLRS[i] = lerpColor(color("steelblue"), color("gold"), random());
	}
	CLRS[NUM-1] = lerpColor(color("darkred"), color("darkorange"), random());

	strokeWeight(2);
	noiseSeed(~~random(999999));
}

function draw() {
	background(2, 2, 12);

	for (let i = 0; i < NUM; i++) {
		stroke(CLRS[i]);
		drawLayer(SZE/(NUM-i+1)); // reverse order to draw smallest first
	}

	drawMsg("Noise Layers (epi) #genuary2502")
}

function drawLayer(SZE) {
	for (let y = 0; y < height; y += SZE) {		
		for (let x = 0; x < width; x += SZE) {
			const n = noise(SZE + x/SZE/12, SZE + y/SZE/12, frameCount/231);
			if (n < MAR) {
				// nothing
			} else if (n < 0.5) {
				line(x, y+SZE, x+SZE, y+SZE);
				// line(x, y+SZE/2, x+SZE, y+SZE/2);
			} else if (n < 1 - MAR) {
				line(x+SZE, y, x+SZE, y+SZE);
				// line(x+SZE/2, y, x+SZE/2, y+SZE);
			} else {
				// notinhg
			}
		}
	}
}

function mouseClicked() {
	if (mouseButton === LEFT) setup();
}

function drawMsg(msg) {
	push();

	fill("black")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 1, 1)

	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)

	pop();
}
